"use client";
/* eslint-disable react-hooks/set-state-in-effect, react-hooks/exhaustive-deps, @next/next/no-img-element */

import Link from "next/link";
import { useEffect, useState } from "react";
import { ArrowUp, ArrowDown, ChevronRight, ExternalLink, FileImage, LoaderCircle, Plus, Save, Search, Trash2, Upload, X } from "lucide-react";
import { useRouter } from "next/navigation";
import { adminDownload, adminGet, adminLogin, adminMutate, type AdminUser, type ApiPagination } from "@/lib/admin-api";

type ContentItem = Record<string, unknown> & { id: number; status?: string; title?: string; name?: string; slug?: string };
type Field = { key: string; label: string; type?: "text" | "textarea" | "number" | "checkbox" | "array" | "date" | "url"; required?: boolean };

const contentConfigs: Record<string, { resource: string; title: string; description: string; fields: Field[]; publicPath?: string }> = {
  services: { resource: "services", title: "Service management", description: "Maintain the published service catalogue and service detail pages.", publicPath: "/services", fields: [{ key: "title", label: "Title", required: true }, { key: "slug", label: "Slug" }, { key: "short_title", label: "Short title" }, { key: "icon", label: "Icon name" }, { key: "excerpt", label: "Excerpt", type: "textarea" }, { key: "description", label: "Description", type: "textarea", required: true }, { key: "benefits", label: "Benefits, one per line", type: "array" }, { key: "deliverables", label: "Deliverables, one per line", type: "array" }, { key: "status", label: "Status" }] },
  packages: { resource: "packages", title: "Pricing & packages", description: "Manage service fee packages. Advertising budgets remain separate.", publicPath: "/pricing", fields: [{ key: "name", label: "Name", required: true }, { key: "slug", label: "Slug" }, { key: "eyebrow", label: "Eyebrow" }, { key: "price", label: "Service fee", type: "text" }, { key: "price_label", label: "Price label" }, { key: "price_note", label: "Price note" }, { key: "description", label: "Description", type: "textarea" }, { key: "features", label: "Features, one per line", type: "array" }, { key: "is_featured", label: "Featured package", type: "checkbox" }, { key: "status", label: "Status" }] },
  portfolio: { resource: "portfolio-projects", title: "Portfolio & case studies", description: "Manage project summaries and publication status for the public portfolio.", publicPath: "/portfolio", fields: [{ key: "title", label: "Title", required: true }, { key: "slug", label: "Slug" }, { key: "client_label", label: "Client label" }, { key: "category", label: "Category", required: true }, { key: "year", label: "Year" }, { key: "initials", label: "Initials" }, { key: "accent", label: "Accent" }, { key: "summary", label: "Summary", type: "textarea" }, { key: "result_summary", label: "Result summary", type: "textarea" }, { key: "challenge", label: "Challenge", type: "textarea" }, { key: "strategy", label: "Strategy", type: "textarea" }, { key: "status", label: "Status" }] },
  "case-studies": { resource: "case-studies", title: "Case studies", description: "Attach a structured case study to a portfolio project and keep its publication state controlled.", publicPath: "/portfolio", fields: [{ key: "portfolio_project_id", label: "Portfolio project ID", type: "number", required: true }, { key: "body", label: "Case study body", type: "textarea" }, { key: "results", label: "Results, one per line", type: "array" }, { key: "gallery", label: "Gallery media IDs, one per line", type: "array" }, { key: "status", label: "Status" }] },
  "blog": { resource: "blog-posts", title: "Blog management", description: "Write and publish editorial content with controlled visibility.", publicPath: "/blog", fields: [{ key: "title", label: "Title", required: true }, { key: "slug", label: "Slug" }, { key: "excerpt", label: "Excerpt", type: "textarea" }, { key: "body", label: "Article body", type: "textarea", required: true }, { key: "reading_time", label: "Reading time (minutes)", type: "number" }, { key: "blog_category_id", label: "Category ID", type: "number" }, { key: "status", label: "Status" }] },
  "blog-categories": { resource: "blog-categories", title: "Blog categories", description: "Organize blog posts into public categories.", publicPath: "/blog", fields: [{ key: "name", label: "Name", required: true }, { key: "slug", label: "Slug" }, { key: "status", label: "Status" }] },
  testimonials: { resource: "testimonials", title: "Testimonials", description: "Approve and publish partner feedback only when it has been verified by your team.", fields: [{ key: "quote", label: "Quote", type: "textarea", required: true }, { key: "name", label: "Name", required: true }, { key: "role", label: "Role" }, { key: "company", label: "Company" }, { key: "is_approved", label: "Approved", type: "checkbox" }, { key: "status", label: "Status" }] },
  faqs: { resource: "faqs", title: "FAQ management", description: "Keep public answers clear, ordered, and current.", publicPath: "/faq", fields: [{ key: "question", label: "Question", required: true }, { key: "answer", label: "Answer", type: "textarea", required: true }, { key: "category", label: "Category" }, { key: "sort_order", label: "Sort order", type: "number" }, { key: "status", label: "Status" }] },
};

const button = "inline-flex h-10 items-center justify-center gap-2 rounded-lg bg-blue-700 px-4 text-sm font-bold text-white transition hover:bg-blue-800 focus:outline-none focus:ring-4 focus:ring-blue-100 disabled:cursor-not-allowed disabled:opacity-50";
const secondary = "inline-flex h-10 items-center justify-center gap-2 rounded-lg border border-slate-200 bg-white px-4 text-sm font-bold text-slate-700 transition hover:border-blue-300 hover:text-blue-700 focus:outline-none focus:ring-4 focus:ring-blue-100";
const input = "h-11 w-full rounded-lg border border-slate-200 bg-white px-3 text-sm text-slate-900 outline-none transition placeholder:text-slate-400 focus:border-blue-500 focus:ring-4 focus:ring-blue-100";
const textarea = "min-h-28 w-full rounded-lg border border-slate-200 bg-white px-3 py-3 text-sm leading-6 text-slate-900 outline-none transition placeholder:text-slate-400 focus:border-blue-500 focus:ring-4 focus:ring-blue-100";

function PageHeader({ title, description, action }: { title: string; description: string; action?: React.ReactNode }) { return <div className="mb-8 flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><p className="text-xs font-extrabold uppercase tracking-[0.18em] text-blue-700">Northstar admin</p><h1 className="mt-2 text-3xl font-extrabold tracking-[-0.04em] text-slate-950 sm:text-4xl">{title}</h1><p className="mt-3 max-w-2xl text-sm leading-6 text-slate-500">{description}</p></div>{action}</div>; }
function Panel({ children, className = "" }: { children: React.ReactNode; className?: string }) { return <section className={`rounded-2xl border border-slate-200 bg-white shadow-[0_14px_38px_-30px_rgba(15,23,42,0.35)] ${className}`}>{children}</section>; }
function StatusPill({ status }: { status?: string }) { const good = status === "published" || status === "qualified" || status === "approved"; return <span className={`inline-flex rounded-full px-2.5 py-1 text-[11px] font-extrabold capitalize ${good ? "bg-green-50 text-green-700" : status === "archived" || status === "lost" ? "bg-slate-100 text-slate-500" : "bg-amber-50 text-amber-700"}`}>{status ?? "draft"}</span>; }
function Loading() { return <div className="flex items-center gap-2 py-10 text-sm font-semibold text-slate-500"><LoaderCircle className="animate-spin" size={17} /> Loading…</div>; }
function Notice({ message, error = false }: { message: string; error?: boolean }) { return <div className={`rounded-xl border p-4 text-sm ${error ? "border-red-200 bg-red-50 text-red-700" : "border-green-200 bg-green-50 text-green-700"}`}>{message}</div>; }
function Empty({ message = "No records found." }: { message?: string }) { return <div className="rounded-xl border border-dashed border-slate-200 p-10 text-center text-sm text-slate-500">{message}</div>; }

export function AdminLoginPage() {
  const router = useRouter();
  const [email, setEmail] = useState("admin@example.test"); const [password, setPassword] = useState(""); const [remember, setRemember] = useState(true); const [error, setError] = useState<string | null>(null); const [loading, setLoading] = useState(false);
  async function submit(event: React.FormEvent) { event.preventDefault(); setLoading(true); setError(null); try { await adminLogin(email, password, remember); router.push("/admin"); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to sign in."); setLoading(false); } }
  return <main className="flex min-h-screen items-center justify-center bg-slate-50 px-5 py-10"><div className="grid w-full max-w-5xl overflow-hidden rounded-3xl border border-slate-200 bg-white shadow-[0_30px_80px_-40px_rgba(20,61,141,0.35)] lg:grid-cols-[0.9fr_1.1fr]"><div className="hidden bg-blue-700 p-12 text-white lg:block"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-white text-xl font-extrabold text-blue-700">N</div><p className="mt-24 text-sm font-bold uppercase tracking-[0.18em] text-blue-200">Control center</p><h1 className="mt-4 text-4xl font-extrabold leading-tight tracking-[-0.05em]">Keep the next decision clear.</h1><p className="mt-5 max-w-sm leading-7 text-blue-100">Manage the public experience, inquiries, and content from one calm workspace.</p></div><div className="p-7 sm:p-12"><Link href="/" className="text-sm font-bold text-blue-700">← Back to public site</Link><h2 className="mt-14 text-3xl font-extrabold tracking-tight text-slate-950">Welcome back</h2><p className="mt-3 text-sm leading-6 text-slate-500">Sign in with an administrator account to continue.</p>{error && <div className="mt-6"><Notice message={error} error /></div>}<form className="mt-8 grid gap-5" onSubmit={submit}><label className="grid gap-2 text-sm font-bold text-slate-700">Email address<input className={input} type="email" value={email} onChange={(event) => setEmail(event.target.value)} required /></label><label className="grid gap-2 text-sm font-bold text-slate-700">Password<input className={input} type="password" value={password} onChange={(event) => setPassword(event.target.value)} required /></label><label className="flex items-center gap-2 text-sm text-slate-600"><input type="checkbox" checked={remember} onChange={(event) => setRemember(event.target.checked)} className="h-4 w-4 accent-blue-700" /> Keep me signed in</label><button className={`${button} mt-2 h-12`} disabled={loading}>{loading ? <LoaderCircle className="animate-spin" size={17} /> : null}{loading ? "Signing in…" : "Sign in"}</button></form><p className="mt-6 text-xs leading-5 text-slate-400">Administrator access is provisioned by the application owner. Public self-registration is disabled.</p></div></div></main>;
}

export function DashboardPage() {
  const [data, setData] = useState<{ counts: Record<string, number>; leads_by_status: Record<string, number>; leads_by_service: Record<string, number>; follow_ups_due: number; recent_inquiries: Record<string, unknown>[] } | null>(null); const [error, setError] = useState<string | null>(null);
  useEffect(() => { adminGet<{ data: typeof data }>("/admin/dashboard").then((response) => setData(response.data)).catch((reason) => setError(reason instanceof Error ? reason.message : "Unable to load dashboard.")); }, []);
  const cards = data ? [["Total inquiries", data.counts.total_leads, "↗"], ["New inquiries", data.counts.new_leads, "◎"], ["Qualified", data.counts.qualified_leads, "✓"], ["Follow-ups due", data.follow_ups_due, "◷"], ["Published services", data.counts.published_services, "✦"], ["Published articles", data.counts.published_blog_posts, "✎"], ["Published projects", data.counts.published_portfolio_projects, "◫"]] : [];
  return <><PageHeader title="Overview" description="A live view of content health and incoming business inquiries." />{error && <Notice message={error} error />}{!data && !error ? <Loading /> : data && <><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{cards.map(([label, value, icon]) => <Panel key={String(label)} className="p-5"><div className="flex items-center justify-between"><p className="text-sm font-bold text-slate-500">{label}</p><span className="flex h-9 w-9 items-center justify-center rounded-lg bg-blue-50 text-blue-700">{icon}</span></div><p className="mt-7 text-3xl font-extrabold tracking-tight text-slate-950">{value}</p><p className="mt-2 text-xs text-slate-400">Database count</p></Panel>)}</div><div className="mt-6 grid gap-5 lg:grid-cols-2"><Panel className="p-5"><h2 className="font-extrabold text-slate-950">Leads by status</h2><div className="mt-4 grid gap-3">{Object.entries(data.leads_by_status).map(([label, value]) => <div key={label} className="flex items-center justify-between rounded-lg bg-slate-50 px-3 py-2 text-sm"><span className="capitalize text-slate-600">{label.replaceAll("_", " ")}</span><span className="font-extrabold text-slate-950">{value}</span></div>)}</div></Panel><Panel className="p-5"><h2 className="font-extrabold text-slate-950">Leads by service</h2><div className="mt-4 grid gap-3">{Object.entries(data.leads_by_service).map(([label, value]) => <div key={label} className="flex items-center justify-between rounded-lg bg-slate-50 px-3 py-2 text-sm"><span className="capitalize text-slate-600">{label}</span><span className="font-extrabold text-slate-950">{value}</span></div>)}</div></Panel></div><Panel className="mt-6 overflow-hidden"><div className="flex items-center justify-between border-b border-slate-200 px-5 py-4"><div><h2 className="font-extrabold text-slate-950">Recent inquiries</h2><p className="mt-1 text-xs text-slate-500">The latest leads and quote requests stored by the API.</p></div><Link className={secondary} href="/admin/leads">View all <ChevronRight size={15} /></Link></div><InquiryTable items={data.recent_inquiries} /></Panel></>}</>;
}

function InquiryTable({ items }: { items: Record<string, unknown>[] }) { if (!items.length) return <div className="p-6"><Empty message="No inquiries have been received yet." /></div>; return <div className="overflow-x-auto"><table className="w-full min-w-[680px] text-left text-sm"><thead className="bg-slate-50 text-xs uppercase tracking-wide text-slate-400"><tr><th className="px-5 py-3">Name</th><th className="px-5 py-3">Type</th><th className="px-5 py-3">Company</th><th className="px-5 py-3">Status</th><th className="px-5 py-3">Received</th></tr></thead><tbody className="divide-y divide-slate-100">{items.map((item) => <tr key={`${item.type}-${item.id}`}><td className="px-5 py-4"><p className="font-bold text-slate-900">{String(item.name)}</p><p className="mt-1 text-xs text-slate-400">{String(item.email)}</p></td><td className="px-5 py-4 text-slate-600">{item.type === "quote_request" ? "Quote request" : "Contact lead"}</td><td className="px-5 py-4 text-slate-600">{String(item.company_name || "—")}</td><td className="px-5 py-4"><StatusPill status={String(item.status)} /></td><td className="px-5 py-4 text-xs text-slate-500">{new Date(String(item.created_at)).toLocaleDateString()}</td></tr>)}</tbody></table></div>; }

export function ContentManager({ section }: { section: string }) {
  const [variant, setVariant] = useState(section === "portfolio" ? "portfolio-projects" : section); const config = contentConfigs[variant] ?? contentConfigs.services; const [items, setItems] = useState<ContentItem[]>([]); const [meta, setMeta] = useState<ApiPagination<ContentItem>["meta"]>(); const [search, setSearch] = useState(""); const [status, setStatus] = useState(""); const [editing, setEditing] = useState<ContentItem | null>(null); const [loading, setLoading] = useState(true); const [error, setError] = useState<string | null>(null); const [notice, setNotice] = useState<string | null>(null);
  async function load() { setLoading(true); setError(null); try { const query = new URLSearchParams({ per_page: "15", ...(search ? { search } : {}), ...(status ? { status } : {}) }); const response = await adminGet<ApiPagination<ContentItem>>(`/admin/content/${config.resource}?${query}`); setItems(response.data); setMeta(response.meta); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to load content."); } finally { setLoading(false); } }
  useEffect(() => { const timer = setTimeout(load, 180); return () => clearTimeout(timer); }, [variant, search, status]);
  async function action(item: ContentItem, type: "publish" | "unpublish" | "delete") { if (type === "delete" && !window.confirm("Archive this content item?")) return; setNotice(null); try { await adminMutate(`/admin/content/${config.resource}/${item.id}/${type === "delete" ? "" : type}`, type === "delete" ? "DELETE" : "POST"); setNotice(type === "delete" ? "Content archived." : `Content ${type === "publish" ? "published" : "unpublished"}.`); load(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Action failed."); } }
  return <><PageHeader title={config.title} description={config.description} action={<button className={button} onClick={() => setEditing({ id: 0, status: "draft" })}><Plus size={16} /> Add new</button>} />{section === "portfolio" && <div className="mb-5 flex gap-2"><button className={variant === "portfolio-projects" ? button : secondary} onClick={() => setVariant("portfolio-projects")}>Projects</button><button className={variant === "case-studies" ? button : secondary} onClick={() => setVariant("case-studies")}>Case studies</button></div>}{notice && <div className="mb-5"><Notice message={notice} /></div>}{error && <div className="mb-5"><Notice message={error} error /></div>}<Panel><div className="flex flex-col gap-3 border-b border-slate-200 p-4 sm:flex-row"><label className="relative flex-1"><Search size={16} className="absolute left-3 top-3 text-slate-400" /><input className={`${input} pl-9`} value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search content" /></label><select className={`${input} sm:w-44`} value={status} onChange={(event) => setStatus(event.target.value)}><option value="">All statuses</option><option value="published">Published</option><option value="draft">Draft</option><option value="archived">Archived</option></select></div>{loading ? <div className="p-5"><Loading /></div> : !items.length ? <div className="p-5"><Empty /></div> : <div className="overflow-x-auto"><table className="w-full min-w-[820px] text-left text-sm"><thead className="bg-slate-50 text-xs uppercase tracking-wide text-slate-400"><tr><th className="px-5 py-3">Content</th><th className="px-5 py-3">Status</th><th className="px-5 py-3">Updated</th><th className="px-5 py-3 text-right">Actions</th></tr></thead><tbody className="divide-y divide-slate-100">{items.map((item) => { const label = String(item.title ?? item.name ?? item.question ?? item.quote ?? "Untitled"); return <tr key={item.id}><td className="px-5 py-4"><p className="font-bold text-slate-900">{label}</p><p className="mt-1 text-xs text-slate-400">{item.slug ? `/${String(item.slug)}` : `ID ${item.id}`}</p></td><td className="px-5 py-4"><StatusPill status={item.status} /></td><td className="px-5 py-4 text-xs text-slate-500">{item.updated_at ? new Date(String(item.updated_at)).toLocaleDateString() : "—"}</td><td className="px-5 py-4"><div className="flex justify-end gap-2"><button className={secondary} onClick={() => setEditing(item)}>Edit</button>{item.slug && config.publicPath && <Link className={`${secondary} px-3`} href={`${config.publicPath}/${String(item.slug)}`} target="_blank" aria-label="Preview"><ExternalLink size={15} /></Link>}{item.status === "published" ? <button className={`${secondary} px-3`} onClick={() => action(item, "unpublish")}>Unpublish</button> : <button className={`${button} px-3`} onClick={() => action(item, "publish")}>Publish</button>}<button className="rounded-lg border border-red-100 px-3 text-red-600 hover:bg-red-50" onClick={() => action(item, "delete")} aria-label="Archive"><Trash2 size={15} /></button></div></td></tr>; })}</tbody></table></div>}<div className="flex items-center justify-between border-t border-slate-200 px-5 py-4 text-xs text-slate-500"><span>{meta?.total ?? items.length} records</span><span>Page {meta?.current_page ?? 1} of {meta?.last_page ?? 1}</span></div></Panel>{editing && <ContentEditor config={config} item={editing} onClose={() => setEditing(null)} onSaved={() => { setEditing(null); setNotice("Content saved."); load(); }} />}</>;
}

function ContentEditor({ config, item, onClose, onSaved }: { config: typeof contentConfigs[string]; item: ContentItem; onClose: () => void; onSaved: () => void }) {
  const [form, setForm] = useState<Record<string, unknown>>(() => Object.fromEntries(config.fields.map((field) => [field.key, field.type === "array" ? Array.isArray(item[field.key]) ? (item[field.key] as unknown[]).join("\n") : "" : item[field.key] ?? (field.type === "checkbox" ? false : "")] ))); const [saving, setSaving] = useState(false); const [error, setError] = useState<string | null>(null); const isNew = item.id === 0;
  function update(key: string, value: unknown) { setForm((current) => ({ ...current, [key]: value })); }
  async function save(event: React.FormEvent) { event.preventDefault(); setSaving(true); setError(null); const payload = { ...form }; for (const field of config.fields) { if (field.type === "array") payload[field.key] = String(payload[field.key] ?? "").split("\n").map((value) => value.trim()).filter(Boolean); if (field.type === "number" && payload[field.key] !== "") payload[field.key] = Number(payload[field.key]); } try { await adminMutate(`/admin/content/${config.resource}${isNew ? "" : `/${item.id}`}`, isNew ? "POST" : "PUT", payload); onSaved(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to save content."); setSaving(false); } }
  return <div className="fixed inset-0 z-[60] overflow-y-auto bg-slate-950/30 p-4 sm:p-8"><div className="mx-auto max-w-4xl rounded-2xl border border-slate-200 bg-white shadow-2xl"><div className="flex items-center justify-between border-b border-slate-200 px-5 py-4"><div><p className="text-xs font-bold uppercase tracking-[0.16em] text-blue-700">{isNew ? "Create" : "Edit"}</p><h2 className="mt-1 text-xl font-extrabold text-slate-950">{config.title}</h2></div><button onClick={onClose} className="rounded-lg p-2 text-slate-400 hover:bg-slate-100" aria-label="Close editor"><X size={19} /></button></div><form onSubmit={save} className="grid gap-5 p-5 sm:grid-cols-2">{error && <div className="sm:col-span-2"><Notice message={error} error /></div>}{config.fields.map((field) => <label key={field.key} className={`grid gap-2 text-sm font-bold text-slate-700 ${field.type === "textarea" || field.type === "array" ? "sm:col-span-2" : ""}`}>{field.label}{field.type === "textarea" || field.type === "array" ? <textarea className={textarea} value={String(form[field.key] ?? "")} onChange={(event) => update(field.key, event.target.value)} required={field.required} /> : field.type === "checkbox" ? <span className="flex h-11 items-center gap-2"><input className="h-4 w-4 accent-blue-700" type="checkbox" checked={Boolean(form[field.key])} onChange={(event) => update(field.key, event.target.checked)} /> Enabled</span> : field.key === "status" ? <select className={input} value={String(form[field.key] ?? "draft")} onChange={(event) => update(field.key, event.target.value)}><option value="draft">Draft</option><option value="published">Published</option><option value="archived">Archived</option></select> : <input className={input} type={field.type === "number" ? "number" : field.type === "url" ? "url" : "text"} value={String(form[field.key] ?? "")} onChange={(event) => update(field.key, event.target.value)} required={field.required} />}</label>)}<div className="flex justify-end gap-3 border-t border-slate-200 pt-5 sm:col-span-2"><button type="button" className={secondary} onClick={onClose}>Cancel</button><button className={button} disabled={saving}>{saving ? <LoaderCircle className="animate-spin" size={16} /> : <Save size={16} />}{saving ? "Saving…" : "Save changes"}</button></div></form></div></div>;
}

export function LeadsPage() {
  const [kind, setKind] = useState<"leads" | "quote-requests">("leads"); const [items, setItems] = useState<Record<string, unknown>[]>([]); const [meta, setMeta] = useState<ApiPagination<Record<string, unknown>>["meta"]>(); const [staff, setStaff] = useState<AdminUser[]>([]); const [selected, setSelected] = useState<Record<string, unknown> | null>(null); const [search, setSearch] = useState(""); const [status, setStatus] = useState(""); const [service, setService] = useState(""); const [followUpDue, setFollowUpDue] = useState(false); const [sort, setSort] = useState("created_at"); const [loading, setLoading] = useState(true); const [error, setError] = useState<string | null>(null);
  const statuses = [["new", "New"], ["contacted", "Contacted"], ["qualified", "Qualified"], ["proposal_sent", "Proposal sent"], ["won", "Won"], ["lost", "Lost"], ["spam", "Spam"], ["archived", "Archived"]];
  function queryString() { const params = new URLSearchParams({ per_page: "30", sort }); if (search) params.set("search", search); if (status) params.set("status", status); if (service) params.set("service", service); if (followUpDue) params.set("follow_up_due", "1"); return params.toString(); }
  async function load() { setLoading(true); try { const response = await adminGet<ApiPagination<Record<string, unknown>>>("/admin/" + kind + "?" + queryString()); setItems(response.data); setMeta(response.meta); setError(null); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to load inquiries."); } finally { setLoading(false); } }
  useEffect(() => { const timer = setTimeout(() => { void load(); }, 180); return () => clearTimeout(timer); }, [kind, search, status, service, followUpDue, sort]);
  useEffect(() => { adminGet<{ data: AdminUser[] }>("/admin/lead-staff").then((response) => setStaff(response.data)).catch(() => setStaff([])); }, []);
  async function openDetail(item: Record<string, unknown>) { try { const response = await adminGet<{ data: Record<string, unknown> }>("/admin/" + kind + "/" + item.id); setSelected(response.data); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to load inquiry details."); } }
  async function updateStatus(item: Record<string, unknown>, nextStatus: string) { try { await adminMutate("/admin/" + kind + "/" + item.id, "PATCH", { status: nextStatus }); await load(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to update status."); } }
  async function downloadCsv() { try { const blob = await adminDownload("/admin/leads/export?kind=" + kind + "&" + queryString()); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = kind === "leads" ? "leads.csv" : "quote-requests.csv"; link.click(); URL.revokeObjectURL(url); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to export inquiries."); } }
  return <><PageHeader title="Leads & inquiries" description="Review contact leads and quote requests, update qualification status, assign follow-ups, and keep the sales trail current." action={<button className={button} onClick={downloadCsv}>Export CSV</button>} /><div className="mb-5 flex flex-wrap gap-2"><button className={kind === "leads" ? button : secondary} onClick={() => { setKind("leads"); setSelected(null); }}>Contact leads</button><button className={kind === "quote-requests" ? button : secondary} onClick={() => { setKind("quote-requests"); setSelected(null); }}>Quote requests</button></div>{error && <div className="mb-5"><Notice message={error} error /></div>}<Panel><div className="grid gap-3 border-b border-slate-200 p-4 md:grid-cols-[minmax(220px,1fr)_repeat(4,minmax(130px,auto))]"><label className="relative"><Search size={16} className="absolute left-3 top-3 text-slate-400" /><span className="sr-only">Search inquiries</span><input className={input + " pl-9"} placeholder="Search name, email, or company" value={search} onChange={(event) => setSearch(event.target.value)} /></label><select className={input} aria-label="Status" value={status} onChange={(event) => setStatus(event.target.value)}><option value="">All statuses</option>{statuses.map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select><select className={input} aria-label="Service" value={service} onChange={(event) => setService(event.target.value)}><option value="">All services</option>{["seo", "social-media", "paid-advertising", "branding", "website-development", "content-video", "email-marketing", "analytics"].map((value) => <option key={value} value={value}>{value.replaceAll("-", " ")}</option>)}</select><select className={input} aria-label="Sort" value={sort} onChange={(event) => setSort(event.target.value)}><option value="created_at">Newest first</option><option value="follow_up_at">Follow-up date</option><option value="full_name">Name</option><option value="status">Status</option></select><label className="flex items-center gap-2 text-xs font-bold text-slate-600"><input type="checkbox" checked={followUpDue} onChange={(event) => setFollowUpDue(event.target.checked)} className="h-4 w-4 accent-blue-700" />Due follow-ups</label></div>{loading ? <div className="p-5"><Loading /></div> : !items.length ? <div className="p-5"><Empty message="No inquiries match this view." /></div> : <div className="overflow-x-auto"><table className="w-full min-w-[920px] text-left text-sm"><thead className="bg-slate-50 text-xs uppercase tracking-wide text-slate-400"><tr><th className="px-5 py-3">Contact</th><th className="px-5 py-3">Company</th><th className="px-5 py-3">Service</th><th className="px-5 py-3">Status</th><th className="px-5 py-3">Follow-up</th><th className="px-5 py-3">Received</th></tr></thead><tbody className="divide-y divide-slate-100">{items.map((item) => <tr key={String(item.id)} className="hover:bg-slate-50"><td className="px-5 py-4"><button className="text-left" onClick={() => openDetail(item)}><p className="font-bold text-blue-700">{String(item.full_name)}</p><p className="mt-1 text-xs text-slate-400">{String(item.email)}</p></button></td><td className="px-5 py-4 text-slate-600">{String(item.company_name || "—")}</td><td className="px-5 py-4 text-slate-600">{kind === "quote-requests" ? String((item.service as { title?: string } | null)?.title || "—") : "Contact inquiry"}</td><td className="px-5 py-4"><select aria-label={"Update status for " + String(item.full_name)} className="rounded-lg border border-slate-200 bg-white px-2 py-2 text-xs font-bold" value={String(item.status)} onChange={(event) => updateStatus(item, event.target.value)}>{statuses.map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></td><td className="px-5 py-4 text-xs text-slate-500">{item.follow_up_at ? new Date(String(item.follow_up_at)).toLocaleDateString() : "—"}</td><td className="px-5 py-4 text-xs text-slate-500">{item.created_at ? new Date(String(item.created_at)).toLocaleDateString() : "—"}</td></tr>)}</tbody></table></div>}<div className="border-t border-slate-200 px-5 py-4 text-xs text-slate-500">{meta?.total ?? items.length} records · Page {meta?.current_page ?? 1} of {meta?.last_page ?? 1}</div></Panel>{selected && <LeadDetailPanel kind={kind} item={selected} staff={staff} statuses={statuses} onClose={() => setSelected(null)} onSaved={() => { setSelected(null); void load(); }} />}</>;
}

function LeadDetailPanel({ kind, item, staff, statuses, onClose, onSaved }: { kind: "leads" | "quote-requests"; item: Record<string, unknown>; staff: AdminUser[]; statuses: string[][]; onClose: () => void; onSaved: () => void }) {
  const [status, setStatus] = useState(String(item.status ?? "new")); const [assignedTo, setAssignedTo] = useState(String(item.assigned_to ?? "")); const [followUpAt, setFollowUpAt] = useState(item.follow_up_at ? new Date(String(item.follow_up_at)).toISOString().slice(0, 16) : ""); const [note, setNote] = useState(""); const [saving, setSaving] = useState(false); const [error, setError] = useState<string | null>(null);
  const isQuote = kind === "quote-requests"; const notes = Array.isArray(item.notes) ? item.notes as Record<string, unknown>[] : []; const [noteItems, setNoteItems] = useState(notes);
  async function save() { setSaving(true); setError(null); try { await adminMutate("/admin/" + kind + "/" + item.id, "PATCH", { status, assigned_to: assignedTo ? Number(assignedTo) : null, follow_up_at: followUpAt || null }); onSaved(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to save inquiry."); } finally { setSaving(false); } }
  async function addNote() { if (!note.trim()) return; setSaving(true); try { await adminMutate("/admin/leads/" + item.id + "/notes", "POST", { note }); const response = await adminGet<{ data: Record<string, unknown> }>("/admin/leads/" + item.id); setNoteItems(Array.isArray(response.data.notes) ? response.data.notes as Record<string, unknown>[] : []); setNote(""); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to add note."); } finally { setSaving(false); } }
  async function archive() { if (!window.confirm("Archive this inquiry?")) return; setSaving(true); try { await adminMutate("/admin/" + kind + "/" + item.id + "/archive", "POST"); onSaved(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to archive inquiry."); } finally { setSaving(false); } }
  return <div className="fixed inset-0 z-[70] bg-slate-950/30 p-4 sm:p-8"><div className="ml-auto flex h-full max-w-2xl flex-col overflow-hidden rounded-2xl bg-white shadow-2xl"><div className="flex items-center justify-between border-b border-slate-200 px-5 py-4"><div><p className="text-xs font-bold uppercase tracking-[0.16em] text-blue-700">{isQuote ? "Quote request" : "Contact lead"}</p><h2 className="mt-1 text-xl font-extrabold text-slate-950">{String(item.full_name)}</h2></div><button type="button" className="rounded-lg p-2 text-slate-400 hover:bg-slate-100" onClick={onClose} aria-label="Close inquiry details"><X size={19} /></button></div><div className="flex-1 overflow-y-auto p-5"><div className="grid gap-3 rounded-xl bg-slate-50 p-4 text-sm"><p><span className="font-bold">Email:</span> {String(item.email)}</p><p><span className="font-bold">Phone:</span> {String(item.phone || "—")}</p><p><span className="font-bold">Company:</span> {String(item.company_name || "—")}</p>{isQuote ? <><p><span className="font-bold">Service:</span> {String((item.service as { title?: string } | null)?.title || "—")}</p><p><span className="font-bold">Budget:</span> {String(item.budget_range || "—")}</p><p><span className="font-bold">Description:</span> {String(item.project_description || "—")}</p><p><span className="font-bold">Attachment:</span> {item.attachment_path ? "Stored securely for authorized review." : "None"}</p></> : <><p><span className="font-bold">Subject:</span> {String(item.subject || "—")}</p><p className="whitespace-pre-wrap"><span className="font-bold">Message:</span> {String(item.message || "—")}</p></>}</div><div className="mt-5 grid gap-4 sm:grid-cols-2"><label className="grid gap-2 text-sm font-bold">Status<select className={input} value={status} onChange={(event) => setStatus(event.target.value)}>{statuses.map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label><label className="grid gap-2 text-sm font-bold">Assign to<select className={input} value={assignedTo} onChange={(event) => setAssignedTo(event.target.value)}><option value="">Unassigned</option>{staff.map((user) => <option key={user.id} value={user.id}>{user.name}</option>)}</select></label><label className="grid gap-2 text-sm font-bold sm:col-span-2">Follow-up date and time<input type="datetime-local" className={input} value={followUpAt} onChange={(event) => setFollowUpAt(event.target.value)} /></label></div>{!isQuote && <div className="mt-6"><h3 className="font-extrabold">Internal notes</h3><div className="mt-3 grid gap-3">{noteItems.map((entry) => <div key={String(entry.id)} className="rounded-lg border border-slate-200 p-3 text-sm"><p className="whitespace-pre-wrap text-slate-700">{String(entry.note)}</p><p className="mt-2 text-xs text-slate-400">{String((entry.user as { name?: string } | null)?.name || "Administrator")}</p></div>)}</div><textarea className={textarea + " mt-3"} value={note} onChange={(event) => setNote(event.target.value)} placeholder="Add an internal note" /><button type="button" className={secondary + " mt-2"} onClick={addNote} disabled={saving}>Add note</button></div>}{error && <div className="mt-5"><Notice message={error} error /></div>}</div><div className="flex flex-wrap justify-between gap-3 border-t border-slate-200 px-5 py-4"><button type="button" className="rounded-lg border border-red-100 px-3 py-2 text-sm font-bold text-red-600 hover:bg-red-50" onClick={archive} disabled={saving}>Archive</button><div className="flex gap-3"><button type="button" className={secondary} onClick={onClose}>Cancel</button><button type="button" className={button} onClick={save} disabled={saving}>{saving ? "Saving…" : "Save changes"}</button></div></div></div></div>;
}

export function MediaPage() {
  const [items, setItems] = useState<Record<string, unknown>[]>([]); const [file, setFile] = useState<File | null>(null); const [alt, setAlt] = useState(""); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [notice, setNotice] = useState<string | null>(null); const [error, setError] = useState<string | null>(null);
  async function load() { setLoading(true); try { const response = await adminGet<ApiPagination<Record<string, unknown>>>("/admin/media?per_page=60"); setItems(response.data); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to load media."); } finally { setLoading(false); } }
  useEffect(() => { load(); }, []);
  async function upload(event: React.FormEvent) { event.preventDefault(); if (!file) return; setSaving(true); setError(null); const body = new FormData(); body.append("file", file); body.append("alt_text", alt); try { await adminMutate("/admin/media", "POST", body); setFile(null); setAlt(""); setNotice("Media uploaded."); load(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Upload failed."); } finally { setSaving(false); } }
  async function remove(id: unknown) { if (!window.confirm("Delete this media asset?")) return; try { await adminMutate(`/admin/media/${id}`, "DELETE"); setNotice("Media deleted."); load(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to delete media."); } }
  return <><PageHeader title="Media library" description="Upload approved brand assets, review metadata, and keep referenced files safe." />{notice && <div className="mb-5"><Notice message={notice} /></div>}{error && <div className="mb-5"><Notice message={error} error /></div>}<Panel className="mb-6 p-5"><form onSubmit={upload} className="grid gap-4 md:grid-cols-[1fr_1fr_auto] md:items-end"><label className="grid gap-2 text-sm font-bold text-slate-700">Image file<input className={`${input} h-auto py-2`} type="file" accept="image/jpeg,image/png,image/webp,image/svg+xml,image/x-icon" onChange={(event) => setFile(event.target.files?.[0] ?? null)} required /></label><label className="grid gap-2 text-sm font-bold text-slate-700">Alt text<input className={input} value={alt} onChange={(event) => setAlt(event.target.value)} placeholder="Describe the image" /></label><button className={button} disabled={!file || saving}><Upload size={16} />{saving ? "Uploading…" : "Upload asset"}</button></form><p className="mt-3 text-xs text-slate-400">Images only, maximum 10 MB. Files are stored through Laravel&apos;s configured public disk.</p></Panel>{loading ? <Loading /> : !items.length ? <Empty message="No media assets have been uploaded." /> : <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">{items.map((item) => <Panel key={String(item.id)} className="overflow-hidden"><div className="flex h-44 items-center justify-center bg-slate-100">{String(item.mime_type).startsWith("image/") ? <img src={String(item.url)} alt={String(item.alt_text || item.name)} className="h-full w-full object-cover" /> : <FileImage className="text-slate-400" size={32} />}</div><div className="p-4"><p className="truncate text-sm font-bold text-slate-900">{String(item.name)}</p><p className="mt-1 text-xs text-slate-400">{Math.round(Number(item.size || 0) / 1024)} KB</p><div className="mt-4 flex justify-end"><button className="rounded-lg border border-red-100 px-3 py-2 text-xs font-bold text-red-600 hover:bg-red-50" onClick={() => remove(item.id)}><Trash2 size={14} /></button></div></div></Panel>)}</div>}</>;
}

type Settings = Record<string, unknown>;
export function SettingsPage({ group }: { group: string }) {
  const [value, setValue] = useState<Settings>({}); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [notice, setNotice] = useState<string | null>(null); const [error, setError] = useState<string | null>(null);
  useEffect(() => { setLoading(true); adminGet<{ data: Settings }>(`/admin/settings/${group}`).then((response) => setValue(response.data)).catch((reason) => setError(reason instanceof Error ? reason.message : "Unable to load settings.")).finally(() => setLoading(false)); }, [group]);
  function set(key: string, next: unknown) { setValue((current) => ({ ...current, [key]: next })); }
  async function save(event: React.FormEvent) { event.preventDefault(); setSaving(true); setError(null); try { await adminMutate(`/admin/settings/${group}`, "PUT", { value }); setNotice("Settings saved to the database."); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to save settings."); } finally { setSaving(false); } }
  const labels: Record<string, [string, string]> = { appearance: ["Appearance & branding", "Control validated colors, typography, logo, and favicon references."], hero: ["Hero banner management", "Edit the homepage hero and choose uploaded desktop and mobile artwork."], footer: ["Footer & social links", "Manage the public footer description, contact details, and social destinations."], seo: ["SEO settings", "Set the public site title, description, and social preview asset."], contact: ["Contact information", "Keep public contact details consistent across the site."], general: ["General settings", "Manage core site identity and general configuration."], homepage_sections: ["Homepage sections", "Enable, order, and edit supported homepage sections using the validated registry."] };
  const [title, description] = labels[group] ?? labels.general;
  if (loading) return <><PageHeader title={title} description={description} /><Loading /></>;
  if (group === "seo") return <><PageHeader title={title} description={description} />{notice && <div className="mb-5"><Notice message={notice} /></div>}{error && <div className="mb-5"><Notice message={error} error /></div>}<MediaUploadCard group={group} value={value} setValue={setValue} /><SeoSettingsEditor value={value} setValue={setValue} onSave={save} saving={saving} /></>;
  return <><PageHeader title={title} description={description} />{(group === "hero" || group === "appearance" || group === "footer" || group === "seo") && <MediaUploadCard group={group} value={value} setValue={setValue} />}{group === "hero" && <SettingsPreview value={value} />}{notice && <div className="mb-5"><Notice message={notice} /></div>}{error && <div className="mb-5"><Notice message={error} error /></div>}{group === "homepage_sections" ? <HomepageSectionEditor value={value} setValue={setValue} /> : <Panel><form onSubmit={save} className="grid gap-5 p-5 sm:grid-cols-2">{Object.entries(value).map(([key, current]) => <label key={key} className={`grid gap-2 text-sm font-bold capitalize text-slate-700 ${typeof current === "string" && current.length > 100 ? "sm:col-span-2" : ""}`}>{key.replaceAll("_", " ")}{typeof current === "boolean" ? <span className="flex h-11 items-center gap-2"><input type="checkbox" className="h-4 w-4 accent-blue-700" checked={current} onChange={(event) => set(key, event.target.checked)} /> Enabled</span> : Array.isArray(current) || (typeof current === "object" && current !== null) ? <textarea className={textarea} value={JSON.stringify(current, null, 2)} onChange={(event) => { try { set(key, JSON.parse(event.target.value)); } catch { /* keep editing invalid JSON */ } }} /> : <input className={input} value={String(current ?? "")} onChange={(event) => set(key, event.target.value)} />}</label>)}<div className="flex justify-end border-t border-slate-200 pt-5 sm:col-span-2"><button className={button} disabled={saving}><Save size={16} />{saving ? "Saving…" : "Save settings"}</button></div></form></Panel>}</>;
}

function SeoSettingsEditor({ value, setValue, onSave, saving }: { value: Settings; setValue: React.Dispatch<React.SetStateAction<Settings>>; onSave: (event: React.FormEvent) => void; saving: boolean }) {
  const pages = Array.isArray(value.pages) ? value.pages as Record<string, unknown>[] : [];
  const paths = ["/", "/about", "/services", "/pricing", "/portfolio", "/blog", "/contact", "/get-a-quote", "/faq"];
  function updatePage(path: string, key: string, next: unknown) {
    const existing = pages.find((item) => item.path === path) ?? { path, title: "", description: "", canonical_url: "", search_engine_visibility: "index" };
    const nextPages = pages.some((item) => item.path === path) ? pages.map((item) => item.path === path ? { ...item, [key]: next } : item) : [...pages, { ...existing, [key]: next }];
    setValue((current) => ({ ...current, pages: nextPages }));
  }
  function pageValue(path: string, key: string): string {
    return String((pages.find((item) => item.path === path) ?? {})[key] ?? "");
  }
  return <Panel><form onSubmit={onSave} className="grid gap-6 p-5">
    <div className="grid gap-5 sm:grid-cols-2">
      <label className="grid gap-2 text-sm font-bold text-slate-700">Default SEO title<input className={input} maxLength={60} value={String(value.title ?? "")} onChange={(event) => setValue((current) => ({ ...current, title: event.target.value }))} required /></label>
      <label className="grid gap-2 text-sm font-bold text-slate-700">Default visibility<select className={input} value={String(value.search_engine_visibility ?? "index")} onChange={(event) => setValue((current) => ({ ...current, search_engine_visibility: event.target.value }))}><option value="index">Index</option><option value="noindex">No index</option></select></label>
      <label className="grid gap-2 text-sm font-bold text-slate-700 sm:col-span-2">Default description<textarea className={textarea} maxLength={160} value={String(value.description ?? "")} onChange={(event) => setValue((current) => ({ ...current, description: event.target.value }))} required /></label>
      <label className="grid gap-2 text-sm font-bold text-slate-700">Homepage title<input className={input} maxLength={60} value={String(value.homepage_title ?? "")} onChange={(event) => setValue((current) => ({ ...current, homepage_title: event.target.value }))} required /></label>
      <label className="grid gap-2 text-sm font-bold text-slate-700">Canonical override<input className={input} type="url" placeholder="https://example.com" value={String(value.canonical_url ?? "")} onChange={(event) => setValue((current) => ({ ...current, canonical_url: event.target.value }))} /></label>
      <label className="grid gap-2 text-sm font-bold text-slate-700 sm:col-span-2">Homepage description<textarea className={textarea} maxLength={160} value={String(value.homepage_description ?? "")} onChange={(event) => setValue((current) => ({ ...current, homepage_description: event.target.value }))} required /></label>
      <label className="grid gap-2 text-sm font-bold text-slate-700">Default social image media ID<input className={input} type="number" min="1" value={String(value.og_image_id ?? "")} onChange={(event) => setValue((current) => ({ ...current, og_image_id: event.target.value ? Number(event.target.value) : null }))} /></label>
    </div>
    <div className="border-t border-slate-200 pt-6"><h2 className="text-lg font-extrabold text-slate-950">Page-specific metadata</h2><p className="mt-1 text-sm text-slate-500">Empty page fields inherit the defaults above. Canonical overrides accept HTTPS or HTTP URLs only.</p><div className="mt-5 grid gap-4">{paths.map((path) => <div key={path} className="grid gap-3 rounded-xl border border-slate-200 p-4 lg:grid-cols-[120px_1fr_1fr]"><p className="pt-3 text-sm font-extrabold text-slate-700">{path}</p><div className="grid gap-3"><input className={input} maxLength={60} placeholder="Page title" value={pageValue(path, "title")} onChange={(event) => updatePage(path, "title", event.target.value)} /><input className={input} maxLength={500} type="url" placeholder="Canonical override" value={pageValue(path, "canonical_url")} onChange={(event) => updatePage(path, "canonical_url", event.target.value)} /></div><div className="grid gap-3"><textarea className={textarea + " min-h-11"} maxLength={160} placeholder="Page description" value={pageValue(path, "description")} onChange={(event) => updatePage(path, "description", event.target.value)} /><select className={input} value={pageValue(path, "search_engine_visibility") || "index"} onChange={(event) => updatePage(path, "search_engine_visibility", event.target.value)}><option value="index">Index</option><option value="noindex">No index</option></select></div></div>)}</div></div>
    <div className="flex justify-end border-t border-slate-200 pt-5"><button className={button} disabled={saving}><Save size={16} />{saving ? "Saving…" : "Save SEO settings"}</button></div>
  </form></Panel>;
}

function HomepageSectionEditor({ value, setValue }: { value: Settings; setValue: React.Dispatch<React.SetStateAction<Settings>> }) {
  const sections = Array.isArray(value) ? value as Record<string, unknown>[] : Array.isArray(value.sections) ? value.sections as Record<string, unknown>[] : [];
  function update(next: Record<string, unknown>[]) { setValue((current) => ({ ...current, sections: next })); }
  function move(index: number, direction: -1 | 1) { const next = [...sections]; const target = index + direction; if (target < 0 || target >= next.length) return; [next[index], next[target]] = [next[target], next[index]]; update(next.map((item, order) => ({ ...item, sort_order: order }))); }
  return <Panel><div className="divide-y divide-slate-100">{sections.map((section, index) => <div key={String(section.key)} className="grid gap-4 p-5 md:grid-cols-[auto_1fr_auto] md:items-center"><div className="grid gap-1"><button className="rounded p-1 text-slate-400 hover:bg-slate-100 hover:text-blue-700" onClick={() => move(index, -1)} aria-label="Move section up"><ArrowUp size={15} /></button><button className="rounded p-1 text-slate-400 hover:bg-slate-100 hover:text-blue-700" onClick={() => move(index, 1)} aria-label="Move section down"><ArrowDown size={15} /></button></div><div><p className="font-extrabold capitalize text-slate-900">{String(section.key).replaceAll("_", " ")}</p><div className="mt-3 grid gap-3 sm:grid-cols-2"><input className={input} placeholder="Section heading" value={String(section.heading ?? "")} onChange={(event) => update(sections.map((item, itemIndex) => itemIndex === index ? { ...item, heading: event.target.value } : item))} /><input className={input} placeholder="Section description" value={String(section.description ?? "")} onChange={(event) => update(sections.map((item, itemIndex) => itemIndex === index ? { ...item, description: event.target.value } : item))} /></div></div><label className="flex items-center gap-2 text-sm font-bold text-slate-700"><input type="checkbox" className="h-4 w-4 accent-blue-700" checked={Boolean(section.enabled)} onChange={(event) => update(sections.map((item, itemIndex) => itemIndex === index ? { ...item, enabled: event.target.checked } : item))} /> Enabled</label></div>)}</div><div className="flex justify-end border-t border-slate-200 p-5"><button className={button} onClick={async () => { await adminMutate("/admin/settings/homepage_sections", "PUT", { value: sections }); }}><Save size={16} />Save section layout</button></div></Panel>;
}

export function NavigationPage() {
  const [items, setItems] = useState<Record<string, unknown>[]>([]); const [editing, setEditing] = useState<Record<string, unknown> | null>(null); const [error, setError] = useState<string | null>(null);
  async function load() { try { const response = await adminGet<{ data: Record<string, unknown>[] }>("/admin/navigation"); setItems(response.data); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to load navigation."); } }
  useEffect(() => { load(); }, []);
  return <><PageHeader title="Header & navigation" description="Manage validated public links and their order in the header or footer." action={<button className={button} onClick={() => setEditing({ id: 0, label: "", href: "/", location: "header", sort_order: items.length, is_visible: true, status: "published" })}><Plus size={16} /> Add link</button>} />{error && <Notice message={error} error />}<Panel className="overflow-hidden"><div className="divide-y divide-slate-100">{items.length ? items.map((item) => <div key={String(item.id)} className="flex flex-wrap items-center justify-between gap-4 p-5"><div><p className="font-bold text-slate-900">{String(item.label)}</p><p className="mt-1 text-xs text-slate-400">{String(item.href)} · {String(item.location)}</p></div><div className="flex items-center gap-2"><StatusPill status={String(item.status)} /><button className={secondary} onClick={() => setEditing(item)}>Edit</button><button className="rounded-lg border border-red-100 px-3 py-2 text-red-600 hover:bg-red-50" onClick={async () => { if (window.confirm("Archive this navigation item?")) { await adminMutate(`/admin/navigation/${item.id}`, "DELETE"); load(); } }}><Trash2 size={15} /></button></div></div>) : <div className="p-5"><Empty message="No navigation items configured." /></div>}</div></Panel>{editing && <NavigationEditor item={editing} onClose={() => setEditing(null)} onSaved={() => { setEditing(null); load(); }} />}</>;
}

function NavigationEditor({ item, onClose, onSaved }: { item: Record<string, unknown>; onClose: () => void; onSaved: () => void }) { const [form, setForm] = useState(item); const isNew = item.id === 0; async function save(event: React.FormEvent) { event.preventDefault(); await adminMutate(`/admin/navigation${isNew ? "" : `/${item.id}`}`, isNew ? "POST" : "PUT", form); onSaved(); } return <div className="fixed inset-0 z-[60] overflow-y-auto bg-slate-950/30 p-4"><form onSubmit={save} className="mx-auto mt-10 grid max-w-lg gap-4 rounded-2xl bg-white p-6 shadow-2xl"><div className="flex items-center justify-between"><h2 className="text-xl font-extrabold">Navigation item</h2><button type="button" onClick={onClose}><X size={18} /></button></div>{["label", "href", "location", "sort_order"].map((key) => <label key={key} className="grid gap-2 text-sm font-bold capitalize">{key.replaceAll("_", " ")}<input className={input} value={String(form[key] ?? "")} onChange={(event) => setForm({ ...form, [key]: key === "sort_order" ? Number(event.target.value) : event.target.value })} /></label>)}<label className="flex items-center gap-2 text-sm font-bold"><input type="checkbox" checked={Boolean(form.is_visible)} onChange={(event) => setForm({ ...form, is_visible: event.target.checked })} /> Visible</label><div className="flex justify-end gap-3"><button type="button" className={secondary} onClick={onClose}>Cancel</button><button className={button}><Save size={16} />Save link</button></div></form></div>; }

export function UsersPage() { const [items, setItems] = useState<AdminUser[]>([]); const [roles, setRoles] = useState<Record<string, unknown>[]>([]); const [editing, setEditing] = useState<AdminUser | null>(null); const [error, setError] = useState<string | null>(null); async function load() { try { const [users, roleResponse] = await Promise.all([adminGet<ApiPagination<AdminUser>>("/admin/users"), adminGet<{ data: Record<string, unknown>[] }>("/admin/roles")]); setItems(users.data); setRoles(roleResponse.data); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to load administrators."); } } useEffect(() => { load(); }, []); return <><PageHeader title="User management" description="Provision administrator accounts and assign seeded roles. Public self-registration remains disabled." action={<button className={button} onClick={() => setEditing({ id: 0, name: "", email: "", roles: [] })}><Plus size={16} /> Add administrator</button>} />{error && <Notice message={error} error />}<Panel className="overflow-hidden"><div className="overflow-x-auto"><table className="w-full min-w-[650px] text-left text-sm"><thead className="bg-slate-50 text-xs uppercase tracking-wide text-slate-400"><tr><th className="px-5 py-3">Administrator</th><th className="px-5 py-3">Roles</th><th className="px-5 py-3 text-right">Actions</th></tr></thead><tbody className="divide-y divide-slate-100">{items.map((user) => <tr key={user.id}><td className="px-5 py-4"><p className="font-bold">{user.name}</p><p className="mt-1 text-xs text-slate-400">{user.email}</p></td><td className="px-5 py-4"><div className="flex flex-wrap gap-1">{user.roles?.map((role) => <StatusPill key={role} status={role} />)}</div></td><td className="px-5 py-4 text-right"><button className={secondary} onClick={() => setEditing(user)}>Edit</button></td></tr>)}</tbody></table></div></Panel>{editing && <UserEditor user={editing} roles={roles} onClose={() => setEditing(null)} onSaved={() => { setEditing(null); load(); }} />}</>; }

function UserEditor({ user, roles, onClose, onSaved }: { user: AdminUser; roles: Record<string, unknown>[]; onClose: () => void; onSaved: () => void }) { const [form, setForm] = useState({ name: user.name, email: user.email, password: "", password_confirmation: "", role_ids: roles.filter((role) => user.roles?.includes(String(role.slug))).map((role) => role.id as number) }); async function save(event: React.FormEvent) { event.preventDefault(); await adminMutate(`/admin/users${user.id ? `/${user.id}` : ""}`, user.id ? "PUT" : "POST", form); onSaved(); } return <div className="fixed inset-0 z-[60] overflow-y-auto bg-slate-950/30 p-4"><form onSubmit={save} className="mx-auto mt-10 grid max-w-lg gap-4 rounded-2xl bg-white p-6 shadow-2xl"><div className="flex items-center justify-between"><h2 className="text-xl font-extrabold">Administrator account</h2><button type="button" onClick={onClose}><X size={18} /></button></div><input className={input} placeholder="Name" value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} required /><input className={input} type="email" placeholder="Email" value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} required /><input className={input} type="password" placeholder={user.id ? "New password (optional)" : "Password"} value={form.password} onChange={(event) => setForm({ ...form, password: event.target.value })} required={!user.id} minLength={12} /><input className={input} type="password" placeholder="Confirm password" value={form.password_confirmation} onChange={(event) => setForm({ ...form, password_confirmation: event.target.value })} required={!user.id} minLength={12} /><div className="grid gap-2"><p className="text-sm font-bold">Roles</p>{roles.map((role) => <label key={String(role.id)} className="flex items-center gap-2 text-sm text-slate-600"><input type="checkbox" checked={form.role_ids.includes(Number(role.id))} onChange={(event) => setForm({ ...form, role_ids: event.target.checked ? [...form.role_ids, Number(role.id)] : form.role_ids.filter((id) => id !== Number(role.id)) })} />{String(role.name)}</label>)}</div><div className="flex justify-end gap-3"><button type="button" className={secondary} onClick={onClose}>Cancel</button><button className={button}><Save size={16} />Save account</button></div></form></div>; }

export function RolesPage() { const state = useState<Record<string, unknown>[]>([]); const [roles, setRoles] = state; useEffect(() => { adminGet<{ data: Record<string, unknown>[] }>("/admin/roles").then((response) => setRoles(response.data)); }, []); return <><PageHeader title="Roles & permissions" description="Review the permission matrix seeded for each administrator role." /><div className="grid gap-5 md:grid-cols-3">{roles.map((role) => <Panel key={String(role.id)} className="p-5"><h2 className="text-lg font-extrabold">{String(role.name)}</h2><p className="mt-1 text-xs text-slate-400">{String(role.slug)}</p><div className="mt-5 flex flex-wrap gap-2">{(role.permissions as { slug: string }[] | undefined)?.map((permission) => <span key={permission.slug} className="rounded-full bg-blue-50 px-2.5 py-1 text-[11px] font-bold text-blue-700">{permission.slug}</span>)}</div></Panel>)}</div></>; }

export function AuditLogsPage() { const [items, setItems] = useState<Record<string, unknown>[]>([]); useEffect(() => { adminGet<ApiPagination<Record<string, unknown>>>("/admin/audit-logs?per_page=50").then((response) => setItems(response.data)); }, []); return <><PageHeader title="Audit logs" description="Review administrator actions recorded by the API for content, settings, media, and access changes." /><Panel className="overflow-hidden"><div className="overflow-x-auto"><table className="w-full min-w-[720px] text-left text-sm"><thead className="bg-slate-50 text-xs uppercase tracking-wide text-slate-400"><tr><th className="px-5 py-3">Action</th><th className="px-5 py-3">Administrator</th><th className="px-5 py-3">Target</th><th className="px-5 py-3">Time</th></tr></thead><tbody className="divide-y divide-slate-100">{items.map((item) => <tr key={String(item.id)}><td className="px-5 py-4 font-bold text-slate-900">{String(item.action)}</td><td className="px-5 py-4 text-slate-600">{String((item.user as { name?: string } | null)?.name || "System")}</td><td className="px-5 py-4 text-xs text-slate-500">{String(item.auditable_type || "—")} #{String(item.auditable_id || "—")}</td><td className="px-5 py-4 text-xs text-slate-500">{item.created_at ? new Date(String(item.created_at)).toLocaleString() : "—"}</td></tr>)}</tbody></table>{!items.length && <div className="p-5"><Empty message="No audit events have been recorded." /></div>}</div></Panel></>; }


function MediaUploadCard({ group, value, setValue }: { group: string; value: Settings; setValue: React.Dispatch<React.SetStateAction<Settings>> }) {
  const [file, setFile] = useState<File | null>(null);
  const [key, setKey] = useState(group === "hero" ? "desktop_image_id" : group === "appearance" ? "logo_media_id" : group === "seo" ? "og_image_id" : "logo_media_id");
  const [uploading, setUploading] = useState(false);
  async function upload(event: React.FormEvent) {
    event.preventDefault();
    if (!file) return;
    setUploading(true);
    const body = new FormData();
    body.append("file", file);
    try {
      const response = await adminMutate<{ data: { id: number } }>("/admin/media", "POST", body);
      setValue((current) => ({ ...current, [key]: response.data.id }));
      setFile(null);
    } finally {
      setUploading(false);
    }
  }
  const options = group === "hero" ? ["desktop_image_id", "mobile_image_id"] : group === "appearance" ? ["logo_media_id", "favicon_media_id"] : group === "seo" ? ["og_image_id"] : ["logo_media_id"];
  return <Panel className="mb-6 p-5"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><h2 className="font-extrabold text-slate-950">Asset upload</h2><p className="mt-1 text-xs text-slate-500">Upload through the protected media endpoint, then attach the returned asset to this settings group.</p></div><span className="rounded-full bg-blue-50 px-3 py-1 text-xs font-bold text-blue-700">Selected ID: {String(value[key] ?? "none")}</span></div><form onSubmit={upload} className="mt-4 grid gap-3 sm:grid-cols-[1fr_1fr_auto] sm:items-end"><label className="grid gap-2 text-xs font-bold text-slate-600">Target<select className={input} value={key} onChange={(event) => setKey(event.target.value)}>{options.map((option) => <option key={option} value={option}>{option.replaceAll("_", " ")}</option>)}</select></label><label className="grid gap-2 text-xs font-bold text-slate-600">Image<input className={input} type="file" accept="image/*" onChange={(event) => setFile(event.target.files?.[0] ?? null)} /></label><button className={button} disabled={!file || uploading}><Upload size={15} />{uploading ? "Uploading…" : "Upload & attach"}</button></form></Panel>;
}

function SettingsPreview({ value }: { value: Settings }) {
  return <Panel className="mb-6 overflow-hidden"><div className="relative min-h-56 bg-slate-900 p-7 text-white"><div className="absolute inset-0" style={{ backgroundColor: String(value.overlay_color ?? "#0F172A"), opacity: Number(value.overlay_opacity ?? 0.35) }} /><div className="relative max-w-xl"><p className="text-xs font-bold uppercase tracking-[0.18em] text-blue-200">Unpublished preview</p><h2 className="mt-4 text-3xl font-extrabold tracking-tight">{String(value.heading ?? "Hero heading")}</h2><p className="mt-3 max-w-lg text-sm leading-6 text-slate-200">{String(value.description ?? "Hero description")}</p><button className="mt-5 rounded-lg bg-white px-4 py-2 text-xs font-bold text-blue-700">{String(value.cta_label ?? "Call to action")}</button></div></div></Panel>;
}
